frappe.ui.form.on('Material Indent', {

    company: function(frm) {

        if (!frm.doc.company) return;

        (frm.doc.table_feob || []).forEach(row => {

            if (!row.item_code) return;

            frappe.db.get_doc('Item', row.item_code).then(item => {

                let match = (item.item_defaults || []).find(d => 
                    d.company === frm.doc.company
                );

                if (match) {

                    // ✅ Set in custom field
                    frappe.model.set_value(
                        row.doctype,
                        row.name,
                        "custom_test_warehouse",
                        match.default_warehouse
                    );

                    // ✅ Copy same value to from_warehouse
                    frappe.model.set_value(
                        row.doctype,
                        row.name,
                        "from_warehouse",
                        match.default_warehouse
                    );
                }
            });
        });
    }
});


