function update_child_status(frm) {

    // 🔹 MATERIAL REQUEST
    (frm.doc.custom_material_requests || []).forEach(row => {

        if (!row.material_request) return;

        frappe.db.get_value("Material Request", row.material_request, "docstatus")
            .then(r => {

                let final_status = "Pending";

                if (r.message.docstatus == 1) {
                    final_status = "Completed";
                }

                // ✅ DIRECT ASSIGN (NO DIRTY FORM)
                row.status = final_status;
            });
    });

    // 🔹 STOCK ENTRY
    (frm.doc.custom_stock_entries || []).forEach(row => {

        if (!row.stock_entry) return;

        frappe.db.get_value("Stock Entry", row.stock_entry, "docstatus")
            .then(r => {

                let final_status = "Pending";

                if (r.message.docstatus == 1) {
                    final_status = "Completed";
                }

                // ✅ DIRECT ASSIGN
                row.status = final_status;
            });
    });

    // 🔥 UI REFRESH ONLY (NO SAVE TRIGGER)
    setTimeout(() => {
        frm.refresh_field("custom_material_requests");
        frm.refresh_field("custom_stock_entries");
    }, 500);
}

