function update_indent_status(frm) {

    let has_issue = false;
    let all_completed = true;
    let has_mr = false;

    (frm.doc.table_feob || []).forEach(row => {

        let required = row.qty || 0;
        let issued = row.custom_issue_qty || 0;

        if (issued > 0) {
            has_issue = true;
        }

        if (issued < required) {
            all_completed = false;
        }
    });

    (frm.doc.custom_material_requests || []).forEach(row => {
        if (row.material_request) {
            has_mr = true;
        }
    });

    let new_status = "Open";

    if (all_completed && has_issue) {
        new_status = "Closed";
    }
    else if (has_issue) {
        new_status = "Partially Issued";  // 🔥 main change
    }
    else if (has_mr) {
        new_status = "Purchase Request Raised";
    }

    if (frm.doc.custom_indent_status !== new_status) {
        frm.set_value("custom_indent_status", new_status);
    }
}















