function fetch_stock(frm, row) {
    frappe.call({
        method: "erpnext.stock.utils.get_stock_balance",
        args: {
            item_code: row.item_code,
            warehouse: row.custom_test_warehouse
        },
        callback: function(r) {
            if (r.message !== undefined) {
                frappe.model.set_value(row.doctype, row.name, "stock_qty", r.message);
            }
        }
    });
}











