frappe.ui.form.on('Material Indent', {
    refresh(frm) {

        frm.clear_custom_buttons();
        if (frm.is_new()) return;

        const has_mr = (frm.doc.custom_material_requests || []).length > 0;

        // =====================
        // 🔴 CLOSE BUTTON
        // =====================
        if (frm.doc.custom_indent_status !== "Closed" && has_mr) {

            frm.add_custom_button("Close", () => {

                frappe.confirm("Close this Indent?", () => {

                    frappe.db.set_value(frm.doc.doctype, frm.doc.name, "custom_indent_status", "Closed")
                    .then(() => {
                        return frappe.db.set_value(frm.doc.doctype, frm.doc.name, "custom_closed_by_user_", 1);
                    })
                    .then(() => {
                        frm.reload_doc();
                    });

                });

            });
        }

        // =====================
        // 🟢 REOPEN BUTTON
        // =====================
        if (
            frm.doc.custom_indent_status === "Closed" &&
            Number(frm.doc.custom_closed_by_user_) === 1
        ) {

            frm.add_custom_button("Reopen", () => {

                frappe.confirm("Reopen this Indent?", () => {

                    // ✅ valid statuses only
                    const new_status = has_mr 
                        ? "Purchase Request Raised"
                        : "Open";

                    frappe.db.set_value(frm.doc.doctype, frm.doc.name, "custom_indent_status", new_status)
                    .then(() => {
                        return frappe.db.set_value(frm.doc.doctype, frm.doc.name, "custom_closed_by_user_", 0);
                    })
                    .then(() => {
                        frm.reload_doc();
                    });

                });

            });
        }

        // =====================
        // 🔒 LOCK WHEN CLOSED
        // =====================
        if (frm.doc.custom_indent_status === "Closed") {

            frm.disable_save();

            // ❌ disable child table
            if (frm.fields_dict.table_feob) {
                frm.fields_dict.table_feob.grid.cannot_add_rows = true;
                frm.fields_dict.table_feob.grid.cannot_delete_rows = true;
            }

            // ❌ make fields read only
            frm.fields.forEach(f => {
                if (f.df.fieldname !== "custom_indent_status") {
                    frm.set_df_property(f.df.fieldname, "read_only", 1);
                }
            });

        } else {

            frm.enable_save();

            // ✅ enable child table
            if (frm.fields_dict.table_feob) {
                frm.fields_dict.table_feob.grid.cannot_add_rows = false;
                frm.fields_dict.table_feob.grid.cannot_delete_rows = false;
            }

            // ✅ make fields editable
            frm.fields.forEach(f => {
                frm.set_df_property(f.df.fieldname, "read_only", 0);
            });
        }

        // =====================
        // 🔒 ACTION BUTTON HIDE/SHOW
        // =====================
        setTimeout(() => {
            if (frm.doc.custom_indent_status === "Closed") {
                $('.actions-btn-group').hide();   // hide Actions
            } else {
                $('.actions-btn-group').show();   // show back
            }
        }, 300);

    }
});


