function refresh_all_item_stock(frm) {
    if (!frm.doc.company || !frm.doc.items || !frm.doc.items.length) {
        return;
    }

    frm.doc.items.forEach(function(row) {
        if (row.item_code) {
            fetch_current_stock(frm, row.doctype, row.name);
        }
    });
}

function fetch_current_stock(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    if (!frm.doc.company || !row.item_code) {
        return;
    }

    frappe.call({
        method: "erpnext.stock.dashboard.item_dashboard.get_data",
        args: {
            item_code: row.item_code,
            warehouse: "",
            company: frm.doc.company
        },
        callback: function(r) {
            let total_stock = 0;

            if (r.message && r.message.length) {
                r.message.forEach(function(entry) {
                    total_stock += flt(entry.actual_qty || 0);
                });
            }

            frappe.model.set_value(
                cdt,
                cdn,
                "custom_current_stock",
                total_stock
            );
        }
    });
}

